`timescale 1ps/1ps
// Random traffic through the SoC's SDRAM-region bus into either back end, with
// every read checked against a byte-level reference memory:
//   MEM=1: rtl/memory/ddr3_bridge.sv -> Xilinx MIG 7-series DDR3 controller
//          (generated by fpga/arty_a7/gen_mig.tcl, simulation build with fast
//          calibration) -> Micron DDR3 model (MT41K128M16, 2 Gb x16, -15E);
//   MEM=0: rtl/memory/sdram_ctrl.sv -> tb/unit/sdram_model.sv (the SDR SDRAM
//          the DE10-Lite build uses), for the same measurements.
// The SoC side runs at 50 MHz in both. Traffic: single-beat reads and writes
// with random byte masks, aligned 2- and 4-beat read bursts (the cache's line
// refill is the 4-beat one), requests that must answer with an error, random
// back-pressure on single-beat responses, and one bus_rst with a request in
// flight. Then two
// timed phases: dependent single-beat reads (latency) and back-to-back line
// reads (bandwidth). Prints DDR3_BRIDGE_TB_PASS or SDR_BRIDGE_TB_PASS.
module ddr3_bridge_tb #(parameter int MEM = 1, parameter int OPS = 3000);
  import soc_pkg::*;
  localparam logic [63:0] BASE = platform_pkg::SDRAM_BASE;
  localparam real SOC_PERIOD = 20000.0;                 // 50 MHz
  initial if (MEM != 0 && MEM != 1) $fatal(1, "ddr3_bridge_tb: MEM must be 0 or 1");
  logic clk = 0, rst = 1, bus_rst = 0;
  initial begin #3700; forever #(SOC_PERIOD / 2) clk = ~clk; end   // unrelated phase to the MIG clocks

  logic req_valid = 0, req_ready, rsp_valid, rsp_ready = 1, init_done;
  bus2_req_t req = '0;
  bus2_rsp_t rsp;

  // ------------------------------------------------------------ back ends
  generate if (MEM == 1) begin : ddr3
    logic sys_clk = 0, clk_ref = 0, sys_rst_n = 0;
    always #5000 sys_clk = ~sys_clk;                   // 100 MHz system clock
    always #2500 clk_ref = ~clk_ref;                   // 200 MHz IDELAY reference
    initial #200000 sys_rst_n = 1;
    wire [15:0] dq; wire [1:0] dqs_p, dqs_n, dm;
    wire [13:0] addr; wire [2:0] ba; wire ras_n, cas_n, we_n, reset_n, ck_p, ck_n, cke, cs_n, odt;
    logic ui_clk, ui_rst, calib_done;
    logic [27:0] app_addr; logic [2:0] app_cmd; logic app_en, app_rdy;
    logic [127:0] app_wdf_data, app_rd_data; logic app_wdf_end, app_wdf_wren, app_wdf_rdy;
    logic [15:0] app_wdf_mask; logic app_rd_data_end, app_rd_data_valid;
    mig_ddr3 mig(
      .ddr3_dq(dq), .ddr3_dqs_n(dqs_n), .ddr3_dqs_p(dqs_p), .ddr3_addr(addr), .ddr3_ba(ba),
      .ddr3_ras_n(ras_n), .ddr3_cas_n(cas_n), .ddr3_we_n(we_n), .ddr3_reset_n(reset_n),
      .ddr3_ck_p(ck_p), .ddr3_ck_n(ck_n), .ddr3_cke(cke), .ddr3_cs_n(cs_n), .ddr3_dm(dm), .ddr3_odt(odt),
      .sys_clk_i(sys_clk), .clk_ref_i(clk_ref),
      .app_addr(app_addr), .app_cmd(app_cmd), .app_en(app_en), .app_wdf_data(app_wdf_data), .app_wdf_end(app_wdf_end),
      .app_wdf_mask(app_wdf_mask), .app_wdf_wren(app_wdf_wren), .app_rd_data(app_rd_data), .app_rd_data_end(app_rd_data_end),
      .app_rd_data_valid(app_rd_data_valid), .app_rdy(app_rdy), .app_wdf_rdy(app_wdf_rdy),
      .app_sr_req(1'b0), .app_ref_req(1'b0), .app_zq_req(1'b0), .app_sr_active(), .app_ref_ack(), .app_zq_ack(),
      .ui_clk(ui_clk), .ui_clk_sync_rst(ui_rst), .init_calib_complete(calib_done), .device_temp(),
      .sys_rst(sys_rst_n));
    ddr3_model #(.DEBUG(0)) memory(.rst_n(reset_n), .ck(ck_p), .ck_n(ck_n), .cke(cke), .cs_n(cs_n), .ras_n(ras_n), .cas_n(cas_n),
      .we_n(we_n), .dm_tdqs(dm), .ba(ba), .addr(addr), .dq(dq), .dqs(dqs_p), .dqs_n(dqs_n), .tdqs_n(), .odt(odt));
    ddr3_bridge bridge(.clk(clk), .rst(rst), .bus_rst(bus_rst),
      .req_valid(req_valid), .req_ready(req_ready), .req(req), .rsp_valid(rsp_valid), .rsp_ready(rsp_ready), .rsp(rsp),
      .init_done(init_done), .ui_clk(ui_clk), .ui_rst(ui_rst), .calib_done(calib_done),
      .app_addr(app_addr), .app_cmd(app_cmd), .app_en(app_en), .app_rdy(app_rdy),
      .app_wdf_data(app_wdf_data), .app_wdf_end(app_wdf_end), .app_wdf_mask(app_wdf_mask), .app_wdf_wren(app_wdf_wren),
      .app_wdf_rdy(app_wdf_rdy), .app_rd_data(app_rd_data), .app_rd_data_valid(app_rd_data_valid));
    // The bridge's resets follow the MIG's: held until the MIG's user clock runs.
    always @(posedge clk) rst <= ui_rst;
  end else begin : sdr
    logic sdram_clk = 0;
    always @(clk) sdram_clk <= #(SOC_PERIOD - 1000.0) clk;   // the S5 bench's clock lead
    logic cke, cs_n, ras_n, cas_n, we_n, dq_oe;
    logic [1:0] ba, dqm; logic [12:0] a; logic [15:0] dq_o; wire [15:0] dq;
    assign dq = dq_oe ? dq_o : 16'bz;
    sdram_ctrl ctrl(.clk(clk), .rst(rst), .bus_rst(bus_rst),
      .req_valid(req_valid), .req_ready(req_ready), .req(req), .rsp_valid(rsp_valid), .rsp_ready(rsp_ready), .rsp(rsp),
      .init_done(init_done), .sdram_cke(cke), .sdram_cs_n(cs_n), .sdram_ras_n(ras_n), .sdram_cas_n(cas_n),
      .sdram_we_n(we_n), .sdram_ba(ba), .sdram_a(a), .sdram_dqm(dqm), .sdram_dq_o(dq_o), .sdram_dq_oe(dq_oe),
      .sdram_dq_i(dq), .extra_wait(2'b00), .extra_capture(1'b0));
    sdram_model model(.clk(sdram_clk), .cke(cke), .cs_n(cs_n), .ras_n(ras_n), .cas_n(cas_n), .we_n(we_n),
      .ba(ba), .a(a), .dqm(dqm), .dq(dq));
    initial begin repeat (4) @(posedge clk); rst <= 0; end
  end endgenerate

  // ------------------------------------------------------------- reference
  byte unsigned ref_mem [longint unsigned];            // written bytes only
  int errors = 0, checks = 0, reads = 0, writes = 0, bursts2 = 0, bursts4 = 0, error_reqs = 0;
  longint unsigned cycle = 0;
  always @(posedge clk) cycle++;
  task automatic check(input bit condition, input string message);
    checks++;
    if (!condition) begin errors++; $error("BRIDGE_TB %0t: %s", $realtime, message); end
    if (errors > 20) $fatal(1, "BRIDGE_TB: too many errors");
  endtask
  logic [31:0] rng = 32'h2026_1017;
  function automatic logic [31:0] rnd();
    rng ^= rng << 13; rng ^= rng >> 17; rng ^= rng << 5;
    return rng;
  endfunction
  // Response back-pressure on single beats only: the bus requires burst beats
  // to be taken as they come (the caches do; sdram_ctrl checks it).
  int hold_percent = 30;
  logic [1:0] cur_burst = 0;
  always @(negedge clk) rsp_ready <= cur_burst != 0 || (rnd() % 100) >= hold_percent;

  // One request; collects its responses. first/last are the cycles of the
  // handshake and of the first and last response beats.
  task automatic access(input bit write, input logic [63:0] addr, input logic [63:0] wdata, input logic [7:0] mask,
                        input logic [1:0] burst, output logic [63:0] data [4], output bit error, output int beats,
                        output longint unsigned t_accept, output longint unsigned t_first, output longint unsigned t_last);
    @(negedge clk);
    req_valid = 1; req.write = write; req.addr = addr; req.wdata = wdata; req.mask = mask; req.burst = burst;
    cur_burst = burst;
    #1;
    while (!req_ready) begin @(negedge clk); #1; end
    @(posedge clk);
    t_accept = cycle;
    #1 req_valid = 0;
    beats = 0; error = 0;
    forever begin
      @(posedge clk);
      if (rsp_valid && rsp_ready) begin
        if (beats < 4) data[beats] = rsp.rdata;
        if (beats == 0) t_first = cycle;
        error |= rsp.error;
        beats++;
        if (rsp.last) begin t_last = cycle; break; end
      end
    end
  endtask

  function automatic logic [63:0] expected_word(input logic [63:0] addr, output logic [7:0] known);
    logic [63:0] w = 0;
    known = 0;
    for (int b = 0; b < 8; b++) if (ref_mem.exists(addr + b)) begin w[8*b +: 8] = ref_mem[addr + b]; known[b] = 1; end
    return w;
  endfunction
  task automatic check_read(input logic [63:0] addr, input logic [63:0] got, input string what);
    logic [7:0] known;
    logic [63:0] want = expected_word(addr, known);
    for (int b = 0; b < 8; b++) if (known[b]) begin
      check(got[8*b +: 8] === want[8*b +: 8], $sformatf("%s %h byte %0d: got %h, wrote %h", what, addr, b, got[8*b +: 8], want[8*b +: 8]));
    end
  endtask

  // Addresses: a few hot rows, plus spots across banks, rows and the region's end.
  function automatic logic [63:0] pick_addr(input int align);
    logic [63:0] off;
    case (rnd() % 4)
      0, 1: off = 64'(rnd() % 4096);
      2: off = 64'(rnd() % 64'h400000);
      default: off = 64'h3fff000 + 64'(rnd() % 4096);
    endcase
    return BASE + (off & ~64'(align - 1));
  endfunction

  initial begin
    logic [63:0] data [4], addr, w;
    logic [7:0] mask;
    bit error;
    int beats, kind;
    string tag;
    automatic int n_lat = 0, n_line = 0;
    longint unsigned ta, tf, tl, line_start, line_end;
    automatic longint unsigned lat_sum = 0, lat_min = '1, lat_max = 0;
    wait (!rst);
    wait (init_done);
    $display("BRIDGE_TB init done at %0t ps (cycle %0d)", $realtime, cycle);
    // Seed every address the reads can reach in the hot rows with known data.
    for (int i = 0; i < 4096; i += 8) begin
      w = {rnd(), rnd()};
      access(1, BASE + 64'(i), w, 8'hff, 0, data, error, beats, ta, tf, tl);
      for (int b = 0; b < 8; b++) ref_mem[BASE + 64'(i + b)] = w[8*b +: 8];
      check(!error && beats == 1, "seed write");
    end
    for (int op = 0; op < OPS; op++) begin
      kind = rnd() % 16;
      if (kind < 5) begin                                 // single write, random mask
        addr = pick_addr(8); w = {rnd(), rnd()}; mask = 8'(rnd());
        if (kind == 0) mask = 8'hff;
        access(1, addr, w, mask, 0, data, error, beats, ta, tf, tl);
        check(!error && beats == 1 && data[0] == 0, $sformatf("write %h", addr));
        for (int b = 0; b < 8; b++) if (mask[b]) ref_mem[addr + b] = w[8*b +: 8];
        writes++;
      end else if (kind < 9) begin                        // single read
        addr = pick_addr(8); mask = kind == 5 ? 8'(rnd()) : 8'hff;
        access(0, addr, 0, mask, 0, data, error, beats, ta, tf, tl);
        check(!error && beats == 1, $sformatf("read %h", addr));
        for (int b = 0; b < 8; b++) if (!mask[b]) check(data[0][8*b +: 8] == 0, $sformatf("read %h mask %h: lane %0d not zero", addr, mask, b));
        for (int b = 0; b < 8; b++) if (!mask[b]) data[0][8*b +: 8] = ref_mem.exists(addr + b) ? ref_mem[addr + b] : 8'h00;
        check_read(addr, data[0], "read");
        reads++;
      end else if (kind < 11) begin                       // 2-beat burst
        addr = pick_addr(16);
        access(0, addr, 0, 8'hff, 1, data, error, beats, ta, tf, tl);
        check(!error && beats == 2, $sformatf("burst2 %h beats=%0d", addr, beats));
        for (int i = 0; i < 2; i++) check_read(addr + 8 * i, data[i], "burst2");
        bursts2++;
      end else if (kind < 14) begin                       // 4-beat line
        addr = pick_addr(32);
        access(0, addr, 0, 8'hff, 3, data, error, beats, ta, tf, tl);
        check(!error && beats == 4, $sformatf("line %h beats=%0d", addr, beats));
        for (int i = 0; i < 4; i++) check_read(addr + 8 * i, data[i], "line");
        bursts4++;
      end else begin                                      // must answer with one error beat
        case (rnd() % 6)
          0: access(0, BASE + 64'h4000000, 0, 8'hff, 0, data, error, beats, ta, tf, tl);   // past the region
          1: access(0, BASE - 8, 0, 8'hff, 0, data, error, beats, ta, tf, tl);             // below it
          2: access(0, pick_addr(8) + 4, 0, 8'hff, 0, data, error, beats, ta, tf, tl);     // unaligned
          3: access(1, pick_addr(32), 0, 8'hff, 3, data, error, beats, ta, tf, tl);        // write burst
          4: access(0, pick_addr(32), 0, 8'hff, 2, data, error, beats, ta, tf, tl);        // 3-beat burst
          default: access(0, pick_addr(32) + 8, 0, 8'hff, 3, data, error, beats, ta, tf, tl);  // misaligned line
        endcase
        check(error && beats == 1, "illegal request did not answer with one error beat");
        error_reqs++;
      end
    end
    // bus_rst with a line read in flight: its responses are dropped, and the
    // next access works.
    @(negedge clk);
    req_valid = 1; req.write = 0; req.addr = BASE + 64'h40; req.mask = 8'hff; req.burst = 3; cur_burst = 3;
    #1 while (!req_ready) begin @(negedge clk); #1; end
    @(posedge clk); #1 req_valid = 0;
    @(negedge clk) bus_rst = 1;
    @(negedge clk) bus_rst = 0;
    repeat (200) begin @(posedge clk); check(!rsp_valid, "response after bus_rst"); end
    access(0, BASE + 64'h80, 0, 8'hff, 0, data, error, beats, ta, tf, tl);
    check(!error && beats == 1, "access after bus_rst");
    check_read(BASE + 64'h80, data[0], "after bus_rst");

    // Timed phases, without back-pressure.
    hold_percent = 0;
    repeat (4) @(negedge clk);
    for (int i = 0; i < 64; i++) begin                    // dependent single-beat reads: latency
      addr = BASE + 64'(((i * 1544) % 4096) & ~7);
      access(0, addr, 0, 8'hff, 0, data, error, beats, ta, tf, tl);
      check_read(addr, data[0], "latency read");
      lat_sum += tf - ta; n_lat++;
      if (tf - ta < lat_min) lat_min = tf - ta;
      if (tf - ta > lat_max) lat_max = tf - ta;
    end
    line_start = cycle;
    for (int i = 0; i < 128; i++) begin                   // sequential line reads: bandwidth
      addr = BASE + 64'((i * 32) % 4096);
      access(0, addr, 0, 8'hff, 3, data, error, beats, ta, tf, tl);
      for (int j = 0; j < 4; j++) check_read(addr + 8 * j, data[j], "bandwidth line");
      n_line++;
    end
    line_end = cycle;
    tag = MEM ? "DDR3" : "SDR";
    if (errors == 0)
      $display("%0s_BRIDGE_TB_PASS ops=%0d writes=%0d reads=%0d burst2=%0d lines=%0d error_requests=%0d checks=%0d read_latency_cycles min=%0d mean=%.1f max=%0d line_reads=%0d cycles=%0d bytes_per_cycle=%.2f mbytes_per_s_at_50mhz=%.1f",
               tag, OPS, writes, reads, bursts2, bursts4, error_reqs, checks, lat_min, real'(lat_sum) / n_lat, lat_max,
               n_line, line_end - line_start, 32.0 * n_line / (line_end - line_start), 32.0 * n_line / (line_end - line_start) * 50.0);
    else $fatal(1, "BRIDGE_TB_FAIL errors=%0d", errors);
    $finish;
  end
  initial begin #(2.0e12); $fatal(1, "BRIDGE_TB watchdog"); end
endmodule
